import os

def grep_file(file_name, pattern):
    try:
        with open(file_name, 'r', encoding='utf-8') as file:
            content = file.read()
            matches = content.find(pattern)
            if matches != -1:
                return f"The pattern '{pattern}' was found at position {matches}."
            else:
                return f"The pattern '{pattern}' was not found in the file."
    except FileNotFoundError:
        return f"The file '{file_name}' was not found."
    except Exception as e:
        return f"An error occurred: {e}"

